package cn.workbench;
import org.springframework.stereotype.Service;import java.util.*;import java.time.*;import static cn.workbench.Records.*;
@Service public class TaskService {
 final Store db;final Records r;final Policy p;final Writes w;final OrganizationChanges changes;public TaskService(Store d,Records r,Policy p,Writes w,OrganizationChanges changes){db=d;this.r=r;this.p=p;this.w=w;this.changes=changes;}
 public List<Map<String,Object>> tasks(Policy.Actor a){if(a.administrator())return List.of();return db.tasks(a.company(),a.leader()?null:a.dept()).stream().map(x->r.view(x,true)).filter(t->p.canSeeTask(a,t)).map(t->decorate(a,t)).toList();}
 Map<String,Object> decorate(Policy.Actor a,Map<String,Object> t){t.put("allowedActions",actions(a,t));return t;}
 List<String> actions(Policy.Actor a,Map<String,Object> t){List<String> actions=new ArrayList<>();String s=(String)t.get("status");if(a.leader()&&Domain.companyAllowed(a.role(),a.company(),integer(t,"companyId"))&&(a.role().equals("GROUP_LEADER")||number(t,"creatorId")==a.uid())){if(s.equals("DRAFT"))actions.add("confirm-assign");if(Set.of("PENDING_ACCEPTANCE","PENDING_ACCEPTANCE_WITH_GAP").contains(s))actions.addAll(List.of("accept","reject"));if(!Set.of("COMPLETED","CANCELLED").contains(s))actions.addAll(List.of("cancel","deadline","urge"));}if(a.departmentHead()&&Objects.equals(a.dept(),integer(t,"hostDeptId"))&&Objects.equals(a.company(),integer(t,"companyId"))&&Set.of("IN_PROGRESS","REWORK").contains(s))actions.add("summarize");if(!Set.of("CANCELLED").contains(s))actions.add("comment");if(!Set.of("COMPLETED","CANCELLED").contains(s))actions.add("upload");return actions.stream().filter(a::allows).toList();}
 public Map<String,Object> detail(Policy.Actor a,long id){var t=decorate(a,p.task(a,id));boolean home=(a.leader()&&Domain.companyAllowed(a.role(),a.company(),integer(t,"companyId")))||(a.departmentHead()&&Objects.equals(a.company(),integer(t,"companyId"))&&Objects.equals(a.dept(),integer(t,"hostDeptId")));var subs=r.children(id,"SUB_TASK");if(!home)subs=subs.stream().filter(sub->{try{p.subtask(a,sub,false);return true;}catch(ApiException denied){return false;}}).toList();List<Map<String,Object>> subViews=new ArrayList<>();for(var s:subs){var v=new LinkedHashMap<>(s);v.put("deptName",department(integer(s,"deptId")).get("name"));List<String> ac=subActions(a,t,s);v.put("allowedActions",ac);subViews.add(v);}t.put("subTasks",subViews);
 for(var entry:Map.of("comments","COMMENT","progress","PROGRESS","timeline","TIMELINE","attachments","ATTACHMENT","deadlineRequests","DEADLINE_REQUEST","collaborationRequests","COLLABORATION_REQUEST").entrySet()){var children=r.children(id,entry.getValue());if(!home)children=children.stream().filter(c->Objects.equals(a.company(),integer(c,"companyId"))&&(a.leader()||c.get("deptId")==null||Objects.equals(a.dept(),integer(c,"deptId")))).toList();if(entry.getValue().equals("ATTACHMENT"))children=children.stream().filter(file->p.canSeeAttachment(a,file,t)).map(AttachmentController::publicView).toList();if(entry.getValue().equals("DEADLINE_REQUEST"))children=children.stream().map(c->{var v=new LinkedHashMap<>(c);v.put("allowedActions",a.leader()&&(a.role().equals("GROUP_LEADER")||number(t,"creatorId")==a.uid())&&c.get("status").equals("PENDING")?List.of("approve","reject"):List.of());return (Map<String,Object>)v;}).toList();t.put(entry.getKey(),children);}return t;}
 List<String> subActions(Policy.Actor a,Map<String,Object>t,Map<String,Object>s){try{p.subtask(a,s,true);}catch(ApiException denied){return List.of();}if(Set.of("DRAFT","COMPLETED","CANCELLED").contains(t.get("status")))return List.of();String status=String.valueOf(s.get("status"));if(Set.of("PENDING_ACCEPTANCE","PENDING_ACCEPTANCE_WITH_GAP").contains(t.get("status")))return status.equals("SUBMITTED")&&a.allows("withdraw")?List.of("withdraw"):List.of();List<String> result=new ArrayList<>();if(status.equals("PENDING_RECEIVE")&&a.departmentHead())result.add("receive");if(Set.of("IN_PROGRESS","REWORK").contains(status)){result.addAll(List.of("progress","submit","extend"));if(a.departmentHead())result.addAll(List.of("assign","transfer"));}if(status.equals("SUBMITTED"))result.add("withdraw");return result.stream().filter(a::allows).toList();}
 public Map<String,Object> create(Policy.Actor a,Map<String,Object>b){int company=integer(b,"companyId");p.leader(a,company);String title=text(b,"title",300),content=text(b,"content",20000);Instant deadline=future(b,"deadline");int host=integer(b,"hostDeptId");var hostDept=department(host);if(integer(hostDept,"companyId")!=company)throw invalid("主办部门必须属于任务公司");List<Integer> collaborators=numbers(b.getOrDefault("collaboratorDeptIds",List.of()));if(collaborators.size()>2||new HashSet<>(collaborators).size()!=collaborators.size()||collaborators.contains(host))throw invalid("协办部门最多两个且不得重复主办部门");String priority=String.valueOf(b.getOrDefault("priority","NORMAL"));if(!Set.of("LOW","NORMAL","HIGH").contains(priority))throw invalid("优先级不合法");var task=r.create("TASK",company,null,null,a.uid(),"DRAFT",map("code",nextCode(company),"title",title,"content",content,"priority",priority,"deadline",deadline.toString(),"originalDeadline",deadline.toString(),"hostDeptId",host,"creatorId",a.uid(),"everOverdue",false,"collaboratorDeptIds",collaborators,"rejectCount",0));long id=number(task,"id");createSub(task,hostDept,true);for(int dept:collaborators){var d=department(dept);if(integer(d,"companyId")==company)createSub(task,d,false);else r.create("COLLABORATION_REQUEST",integer(d,"companyId"),dept,id,null,"PENDING",map("sourceCompanyId",company,"taskTitle",title,"deadline",deadline.toString(),"requestedBy",a.uid()));}event(a,task,"CREATE");return decorate(a,task);}
 String nextCode(int company){LocalDate date=LocalDate.now(ZoneId.of("Asia/Shanghai"));db.ensureSequence(company,date);long sequence=db.sequence(company,date)+1;db.advanceSequence(company,date);var c=r.get(company);return "RW-"+c.get("companyCode")+"-"+date.format(java.time.format.DateTimeFormatter.BASIC_ISO_DATE)+"-"+String.format("%04d",sequence);}
 Map<String,Object> department(int id){var d=r.get(id);if(!d.get("kind").equals("DEPARTMENT")||!Boolean.TRUE.equals(d.get("enabled")))throw invalid("部门不存在或已停用");return d;}
 Map<String,Object> createSub(Map<String,Object> task,Map<String,Object> dept,boolean host){return r.create("SUB_TASK",integer(dept,"companyId"),integer(dept,"id"),number(task,"id"),null,"PENDING_RECEIVE",map("isHost",host,"rejectCount",0,"everOverdue",false,"deadline",task.get("deadline"),"percent",0,"summary","","revision",0,"originalDeadline",task.get("deadline")));}
 public Map<String,Object> taskAction(Policy.Actor a,long id,String action,Map<String,Object>b){if(!a.allows(action))throw ApiException.denied();p.task(a,id);var t=r.lock(id);String status=(String)t.get("status");if(!action.equals("urge")&&!action.equals("confirm-assign"))version(t,b);else if(b.containsKey("version"))version(t,b);
 if(action.equals("summarize")){if(!a.departmentHead()||!Objects.equals(a.dept(),integer(t,"hostDeptId"))||!Objects.equals(a.company(),integer(t,"companyId")))throw ApiException.denied();}else {p.leader(a,integer(t,"companyId"));if(!a.role().equals("GROUP_LEADER")&&number(t,"creatorId")!=a.uid())throw ApiException.denied();}
 if(action.equals("urge")){if(Set.of("COMPLETED","CANCELLED").contains(status))throw ApiException.conflict();event(a,t,"URGE");return decorate(a,t);}
 if(action.equals("deadline")){if(Set.of("COMPLETED","CANCELLED").contains(status))throw ApiException.conflict();text(b,"reason",1000);preserveOverdue(t);Instant deadline=future(b,"deadline");t.put("deadline",deadline.toString());for(var sub:r.children(id,"SUB_TASK")){preserveSubOverdue(sub);deadlineHistory(a,t,sub,sub.get("deadline"),deadline.toString(),String.valueOf(b.get("reason")));sub.put("deadline",deadline.toString());r.save(sub);}r.save(t);event(a,t,"DEADLINE_CHANGED");return decorate(a,t);}
 String target=Domain.transition(status,action);if(action.equals("summarize")){var subs=r.children(id,"SUB_TASK");var host=subs.stream().filter(s->Boolean.TRUE.equals(s.get("isHost"))).findFirst().orElseThrow();if(!host.get("status").equals("SUBMITTED"))throw invalid("主办部门须先提交成果");var missing=subs.stream().filter(s->!s.get("status").equals("SUBMITTED")).toList();var pending=r.children(id,"COLLABORATION_REQUEST").stream().filter(c->c.get("status").equals("PENDING")).toList();if(!missing.isEmpty()||!pending.isEmpty()){if(!Boolean.TRUE.equals(b.get("allowGap")))throw new ApiException(409,"MISSING_COLLABORATION","仍有协办成果或跨公司确认待完成");text(b,"reason",1000);target="PENDING_ACCEPTANCE_WITH_GAP";}t.put("summarizedAt",Instant.now().toString());t.put("summaryReason",b.getOrDefault("reason",""));t.put("missingDeptIds",missing.stream().map(s->s.get("deptId")).toList());t.put("summarySubVersions",subs.stream().map(s->map("id",s.get("id"),"version",s.get("version"),"status",s.get("status"))).toList());}
 if(action.equals("reject")){String reason=text(b,"reason",1000);List<Integer> depts=numbers(b.get("deptIds"));if(depts.isEmpty())throw invalid("请选择退回部门");var subs=r.children(id,"SUB_TASK");for(int dept:depts)if(subs.stream().noneMatch(s->integer(s,"deptId")==dept))throw invalid("退回部门不属于此任务");for(var s:subs)if(depts.contains(integer(s,"deptId"))||Boolean.TRUE.equals(s.get("isHost"))){s.put("status","REWORK");s.put("rejectReason",reason);if(depts.contains(integer(s,"deptId")))s.put("rejectCount",integer(s,"rejectCount")+1);s.put("submittedAt",null);r.save(s);}t.put("rejectCount",integer(t,"rejectCount")+1);t.put("summarizedAt",null);}
 if(action.equals("cancel"))text(b,"reason",1000);if(action.equals("accept")){t.put("acceptedAt",Instant.now().toString());for(var sub:r.children(id,"SUB_TASK")){if("SUBMITTED".equals(sub.get("status")))sub.put("status","ACCEPTED");else sub.put("gapClosed",true);r.save(sub);}}
 if(action.equals("cancel"))for(var sub:r.children(id,"SUB_TASK")){sub.put("status","CANCELLED");r.save(sub);}if(action.equals("confirm-assign"))for(var sub:r.children(id,"SUB_TASK")){sub.put("status","PENDING_RECEIVE");sub.put("dispatchedAt",Instant.now().toString());r.save(sub);}preserveOverdue(t);t.put("status",target);r.save(t);event(a,t,action.toUpperCase());return decorate(a,t);}
 public Map<String,Object> subAction(Policy.Actor a,long id,String action,Map<String,Object>b){if(!a.allows(action))throw ApiException.denied();var s=r.get(id);p.subtask(a,s,true);long task=number(s,"taskId");var t=r.lock(task);s=r.lock(id);if(Set.of("COMPLETED","CANCELLED","DRAFT").contains(t.get("status")))throw ApiException.conflict();if(Set.of("PENDING_ACCEPTANCE","PENDING_ACCEPTANCE_WITH_GAP").contains(t.get("status"))&&!action.equals("withdraw"))throw ApiException.conflict();preserveSubOverdue(s);String status=(String)s.get("status");switch(action){
 case "receive"->{if(!a.departmentHead())throw ApiException.denied();Domain.require(status,"PENDING_RECEIVE");s.put("status","IN_PROGRESS");if(s.get("firstReceivedAt")==null)s.put("firstReceivedAt",Instant.now().toString());}
 case "assign"->{if(!a.departmentHead())throw ApiException.denied();if(!Set.of("IN_PROGRESS","REWORK").contains(status))throw ApiException.conflict();if(s.get("ownerId")!=null)version(s,b);List<Integer> users=numbers(b.get("userIds"));long owner=number(b,"ownerId");if(users.isEmpty()||!users.contains((int)owner))throw invalid("主责人须在承办人列表中");for(int user:users)validMember(user,integer(s,"companyId"),integer(s,"deptId"));if(s.get("ownerId")!=null&&Jsons.number(s.get("ownerId"))!=owner)changes.apply(a,s,owner,text(b,"reason",1000));else changes.initialOwner(s,owner);db.clearAssignees(id);for(int user:users)db.assign(id,user);s.put("ownerId",owner);s.put("status","IN_PROGRESS");}
 case "transfer"->{if(!a.departmentHead())throw ApiException.denied();if(!Set.of("IN_PROGRESS","REWORK").contains(status))throw ApiException.conflict();version(s,b);String reason=text(b,"reason",1000);long user=number(b,"userId");changes.apply(a,s,user,reason);}
 case "progress"->{if(!Set.of("IN_PROGRESS","REWORK").contains(status))throw ApiException.conflict();int percent=integer(b,"percent");if(percent<0||percent>100)throw invalid("进度须介于0至100");String note=text(b,"note",4000);r.create("PROGRESS",integer(s,"companyId"),integer(s,"deptId"),task,a.uid(),"POSTED",map("subTaskId",id,"authorId",a.uid(),"percent",percent,"note",note));s.put("percent",percent);}
 case "submit"->{version(s,b);if(!Set.of("IN_PROGRESS","REWORK").contains(status))throw ApiException.conflict();String summary=text(b,"summary",20000);int revision=integer(s,"revision")+1;r.create("RESULT_VERSION",integer(s,"companyId"),integer(s,"deptId"),task,a.uid(),"SUBMITTED",map("subTaskId",id,"summary",summary,"revision",revision));s.put("revision",revision);s.put("summary",summary);s.put("submittedAt",Instant.now().toString());s.put("status","SUBMITTED");s.put("percent",100);}
 case "withdraw"->{version(s,b);Domain.require(status,"SUBMITTED");text(b,"reason",1000);s.put("status","IN_PROGRESS");s.put("submittedAt",null);s.put("modificationCount",Jsons.integer(s.getOrDefault("modificationCount",0))+1);t.put("status","REWORK".equals(t.get("status"))?"REWORK":"IN_PROGRESS");t.put("summarizedAt",null);t.put("summarySubVersions",List.of());r.save(t);}
 case "extend"->{text(b,"reason",1000);Instant deadline=future(b,"deadline");if(!deadline.isAfter(instant(s.get("deadline"))))throw invalid("延期截止时间须晚于当前截止时间");var req=r.create("DEADLINE_REQUEST",integer(s,"companyId"),integer(s,"deptId"),task,a.uid(),"PENDING",map("subTaskId",id,"requestedDeadline",deadline.toString(),"reason",b.get("reason"),"originalDeadline",s.get("deadline")));event(a,t,"EXTENSION_REQUEST");return req;}
 default->throw invalid("未知操作");}r.save(s);event(a,t,"SUBTASK_"+action.toUpperCase());s.put("allowedActions",subActions(a,t,s));return s;}
 void deadlineHistory(Policy.Actor actor,Map<String,Object> task,Map<String,Object> sub,Object previous,Object current,String reason){r.create("DEADLINE_CHANGE",integer(sub,"companyId"),integer(sub,"deptId"),number(task,"id"),actor.uid(),"APPROVED",map("subTaskId",sub.get("id"),"previousDeadline",instant(previous).toString(),"currentDeadline",instant(current).toString(),"reason",reason,"actorId",actor.uid()));}
 void validMember(long uid,int company,int dept){var u=db.user(uid);if(u==null||!Boolean.TRUE.equals(u.get("enabled"))||db.scopes(uid).stream().noneMatch(x->Objects.equals(x.get("companyId")==null?null:Jsons.integer(x.get("companyId")),company)&&Objects.equals(x.get("deptId")==null?null:Jsons.integer(x.get("deptId")),dept)))throw invalid("承办人不属于当前部门");}
 public Map<String,Object> comment(Policy.Actor a,long task,Map<String,Object>b){if(!a.allows("comment"))throw ApiException.denied();p.task(a,task);var t=r.lock(task);String content=text(b,"content",8000);for(int mentioned:numbers(b.getOrDefault("mentions",List.of())))if(db.user(mentioned)==null)throw invalid("提及用户不存在");var c=r.create("COMMENT",a.company()==null?integer(t,"companyId"):a.company(),a.dept(),task,a.uid(),"POSTED",map("authorId",a.uid(),"content",content,"mentions",b.getOrDefault("mentions",List.of())));event(a,t,"COMMENT");return c;}
 public List<Map<String,Object>> collaborations(Policy.Actor a){return r.list("COLLABORATION_REQUEST",a.company(),a.leader()?null:a.dept()).stream().filter(c->a.leader()||a.departmentHead()).map(c->{var copy=new LinkedHashMap<>(c);copy.put("allowedActions",c.get("status").equals("PENDING")?List.of("accept","reject"):List.of());return (Map<String,Object>)copy;}).toList();}
 public Map<String,Object> collaboration(Policy.Actor a,long id,String action,Map<String,Object>b){var c=r.lock(id);if(!c.get("kind").equals("COLLABORATION_REQUEST"))throw ApiException.denied();p.company(a,integer(c,"companyId"));if(!a.leader()&&(!a.departmentHead()||!Objects.equals(a.dept(),integer(c,"deptId"))))throw ApiException.denied();Domain.require(String.valueOf(c.get("status")),"PENDING");var t=r.lock(number(c,"taskId"));if(Set.of("COMPLETED","CANCELLED").contains(t.get("status")))throw ApiException.conflict();if(action.equals("accept")){c.put("status","ACCEPTED");createSub(t,department(integer(c,"deptId")),false);}else if(action.equals("reject")){text(b,"reason",1000);c.put("status","REJECTED");c.put("reason",b.get("reason"));}else throw invalid("未知操作");r.save(c);event(a,t,"COLLABORATION_"+action.toUpperCase());return c;}
 public Map<String,Object> deadline(Policy.Actor a,long id,String action,Map<String,Object>b){var req=r.lock(id);if(!req.get("kind").equals("DEADLINE_REQUEST"))throw ApiException.denied();var t=r.lock(number(req,"taskId"));p.leader(a,integer(t,"companyId"));if(!a.role().equals("GROUP_LEADER")&&number(t,"creatorId")!=a.uid())throw ApiException.denied();Domain.require(String.valueOf(req.get("status")),"PENDING");if(Set.of("COMPLETED","CANCELLED").contains(t.get("status")))throw ApiException.conflict();if(action.equals("approve")){var sub=r.lock(number(req,"subTaskId"));preserveOverdue(t);preserveSubOverdue(sub);deadlineHistory(a,t,sub,sub.get("deadline"),req.get("requestedDeadline"),String.valueOf(req.get("reason")));sub.put("deadline",req.get("requestedDeadline"));r.save(sub);if(instant(req.get("requestedDeadline")).isAfter(instant(t.get("deadline")))){t.put("deadline",req.get("requestedDeadline"));r.save(t);}req.put("status","APPROVED");}else if(action.equals("reject")){text(b,"reason",1000);req.put("status","REJECTED");req.put("decisionReason",b.get("reason"));}else throw invalid("未知操作");r.save(req);event(a,t,"EXTENSION_"+action.toUpperCase());return req;}
 static void preserveSubOverdue(Map<String,Object> sub){if(sub.get("submittedAt")!=null){if(instant(sub.get("submittedAt")).isAfter(instant(sub.get("deadline"))))sub.put("everOverdue",true);}else if(!Set.of("CANCELLED","ACCEPTED").contains(sub.get("status"))&&instant(sub.get("deadline")).isBefore(Instant.now()))sub.put("everOverdue",true);}
 void preserveOverdue(Map<String,Object> task){boolean late=Set.of("IN_PROGRESS","REWORK").contains(task.get("status"))&&instant(task.get("deadline")).isBefore(Instant.now());if(task.get("summarizedAt")!=null)late|=instant(task.get("summarizedAt")).isAfter(instant(task.get("deadline")));for(var sub:r.children(number(task,"id"),"SUB_TASK")){preserveSubOverdue(sub);late|=Boolean.TRUE.equals(sub.get("everOverdue"));}if(late)task.put("everOverdue",true);}
 void event(Policy.Actor actor,Map<String,Object> task,String action){
  long taskId=number(task,"id");int taskCompany=integer(task,"companyId");
  r.create("TIMELINE",actor.company()==null?taskCompany:actor.company(),actor.dept(),taskId,actor.uid(),action,map("action",action,"actorId",actor.uid(),"delegationId",actor.delegationId(),"at",Instant.now().toString(),"taskVersion",task.get("version")));
  w.audit(actor,action,taskId);
  Map<String,Map<String,Object>> recipients=new LinkedHashMap<>();
  long creator=number(task,"creatorId");var creatorUser=db.user(creator);
  if(creatorUser!=null&&Boolean.TRUE.equals(creatorUser.get("enabled")))recipients.put(creator+":"+taskCompany,map("user",creator,"company",taskCompany));
  if(!"DRAFT".equals(task.get("status")))for(var sub:r.children(taskId,"SUB_TASK")){
   int company=integer(sub,"companyId"),dept=integer(sub,"deptId");Set<Long> assigned=new HashSet<>(db.assignees(number(sub,"id")));
   if(sub.get("ownerId")!=null)assigned.add(number(sub,"ownerId"));
   for(var user:db.users()){long uid=number(user,"id");if(!Boolean.TRUE.equals(user.get("enabled")))continue;
    boolean eligible=db.scopes(uid).stream().anyMatch(scope->Objects.equals(company,scope.get("companyId")==null?null:Jsons.integer(scope.get("companyId")))&&Objects.equals(dept,scope.get("deptId")==null?null:Jsons.integer(scope.get("deptId")))&&("DEPT_HEAD".equals(scope.get("role"))||assigned.contains(uid)));
    if(eligible)recipients.put(uid+":"+company,map("user",uid,"company",company));
   }
  }
  for(var recipient:recipients.values())db.outbox(map("key",UUID.randomUUID().toString(),"company",recipient.get("company"),"recipient",recipient.get("user"),"task",taskId,"title","任务动态："+action));
 }
 static String text(Map<String,Object>b,String key,int max){Object v=b.get(key);if(!(v instanceof String s)||s.isBlank()||s.length()>max)throw invalid(key+"不能为空且长度须符合限制");return s;}
 static int integer(Map<String,Object>b,String k){if(b.get(k)==null)throw invalid("缺少字段"+k);return Jsons.integer(b.get(k));}static long number(Map<String,Object>b,String k){if(b.get(k)==null)throw invalid("缺少字段"+k);return Jsons.number(b.get(k));}
 static List<Integer> numbers(Object o){if(!(o instanceof List<?> list))throw invalid("列表字段不合法");return list.stream().map(Jsons::integer).toList();}
 static Instant future(Map<String,Object>b,String k){try{Instant instant=Records.instant(b.get(k));if(!instant.isAfter(Instant.now()))throw invalid("截止时间须晚于当前时间");return instant;}catch(Exception e){throw invalid("截止时间须为未来ISO8601时间");}}
 static void version(Map<String,Object>record,Map<String,Object>b){Domain.version(integer(record,"version"),integer(b,"version"));}static ApiException invalid(String message){return new ApiException(422,"VALIDATION_FAILED",message);}
}
